Import ListNotations. Import AX2.
Open Scope Z_scope.
Abbreviation RSEGS := Asan.M.loaded_segments.
Definition ITR : list (Z * nat) := [(440664, 1%nat) ; (440668, 1%nat) ; (455832, 39%nat) ; (455988, 690%nat) ; (458748, 45%nat) ; (483836, 102%nat) ; (524852, 1%nat) ; (524860, 1%nat) ; (527500, 188%nat) ; (529468, 380%nat) ; (562832, 40%nat) ; (604684, 24%nat) ; (604864, 13%nat) ; (605024, 7%nat) ; (1351016, 78%nat) ; (1352376, 108%nat) ; (1352808, 908%nat) ; (1356440, 16%nat) ; (1356504, 61%nat) ; (1377692, 7%nat) ; (1387168, 257%nat) ; (1388196, 62%nat)].
Definition IT : itab := Eval vm_compute in itab_of RSEGS ITR.
Lemma IT_eq : IT = itab_of RSEGS ITR.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,^@'^A'^B!3+^C'^A'^B!2'^D'^E'^F").
Qed.
Lemma IT_sound : itab_sound RSEGS IT.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S01lg^A;g^Gd;!6'^G'^A!2'^D'^E'^F$i;R'^A!2'^H'^E#1!2'^I'^E'^F'^B'^J").
Qed.
